        // Same lock order: mtx_a then mtx_b, avoiding circular wait.
        sb2.release();
        sa2.acquire();
        let ga = ma2.lock().unwrap();
        let gb = mb2.lock().unwrap();
        drop(gb);
        drop(ga);
    });

    let bystander = thread::spawn(move || loop {
        thread::yield_now();
    });

    worker_a.join().unwrap();
    worker_b.join().unwrap();

    println!("DONE a=1 b=1");

